using System;
using UnityEngine;

namespace Framework.Input
{
    /// <summary>
    /// 4方向変換時に入力軸の強さが
    /// 同程度だった場合の優先方向。
    /// </summary>
    public enum DirectionPriority
    {
        /// <summary>
        /// 水平方向を優先する。
        /// </summary>
        Horizontal = 0,

        /// <summary>
        /// 垂直方向を優先する。
        /// </summary>
        Vertical = 1,

        /// <summary>
        /// 前回の方向を優先する。
        /// 前回方向が候補に含まれない場合は
        /// 水平方向を優先する。
        /// </summary>
        PreviousDirection = 2
    }

    /// <summary>
    /// アナログ入力の方向変換を行う汎用クラス。
    ///
    /// デッドゾーン処理、4方向・8方向変換、
    /// 方向判定などの機能を提供する。
    ///
    /// 特定の入力デバイスや入力アセットには依存しない。
    /// </summary>
    public static class InputDirectionUtility
    {
        #region Constants

        /// <summary>
        /// 標準のデッドゾーン。
        /// </summary>
        public const float DefaultDeadZone = 0.3f;

        /// <summary>
        /// 2軸の入力を同程度と判定する標準許容値。
        /// </summary>
        public const float DefaultTieTolerance = 0.05f;

        /// <summary>
        /// 反時計回りに並べた8方向の単位方向。
        /// </summary>
        private static readonly Vector2Int[] EightDirections =
        {
            Vector2Int.right,
            new Vector2Int(1, 1),
            Vector2Int.up,
            new Vector2Int(-1, 1),
            Vector2Int.left,
            new Vector2Int(-1, -1),
            Vector2Int.down,
            new Vector2Int(1, -1)
        };

        #endregion

        #region Dead Zone Methods

        /// <summary>
        /// 入力がデッドゾーン内にあるか確認する。
        /// </summary>
        /// <param name="input">入力ベクトル</param>
        /// <param name="deadZone">デッドゾーンの半径</param>
        /// <returns>無視すべき入力の場合はtrue</returns>
        public static bool IsInDeadZone(
            Vector2 input,
            float deadZone = DefaultDeadZone)
        {
            ValidateDeadZone(deadZone);

            if (!IsFinite(input))
            {
                return true;
            }

            return input.sqrMagnitude <=
                   deadZone * deadZone;
        }

        /// <summary>
        /// 円形デッドゾーンを適用する。
        ///
        /// デッドゾーン外の入力値は変更しない。
        /// </summary>
        /// <param name="input">入力ベクトル</param>
        /// <param name="deadZone">デッドゾーンの半径</param>
        /// <returns>デッドゾーン適用後の入力値</returns>
        public static Vector2 ApplyDeadZone(
            Vector2 input,
            float deadZone = DefaultDeadZone)
        {
            return IsInDeadZone(input, deadZone)
                ? Vector2.zero
                : input;
        }

        /// <summary>
        /// 円形デッドゾーンを適用し、
        /// 残りの入力範囲を0～1へ再割り当てする。
        ///
        /// 入力方向は維持する。
        /// </summary>
        /// <param name="input">入力ベクトル</param>
        /// <param name="deadZone">デッドゾーンの半径</param>
        /// <returns>補正された入力ベクトル</returns>
        public static Vector2 ApplyScaledDeadZone(
            Vector2 input,
            float deadZone = DefaultDeadZone)
        {
            if (IsInDeadZone(input, deadZone))
            {
                return Vector2.zero;
            }

            // 入力の大きさを最大1に制限する。
            float magnitude =
                Mathf.Clamp01(input.magnitude);

            // デッドゾーン外の範囲を0～1に変換する。
            float scaledMagnitude = Mathf.InverseLerp(
                deadZone,
                1f,
                magnitude);

            return input.normalized * scaledMagnitude;
        }

        #endregion

        #region Direction Conversion Methods

        /// <summary>
        /// 2軸入力を上下左右の4方向へ変換する。
        ///
        /// 基本的には絶対値の大きい軸を採用する。
        /// 2軸の強さが同程度の場合は優先設定に従う。
        /// </summary>
        /// <param name="input">入力ベクトル</param>
        /// <param name="deadZone">デッドゾーンの半径</param>
        /// <param name="priority">同程度の入力時の優先方向</param>
        /// <param name="previousDirection">前回の入力方向</param>
        /// <param name="tieTolerance">軸の強さの許容差</param>
        /// <returns>上下左右の単位方向。無入力時はzero</returns>
        public static Vector2Int ToFourDirection(
            Vector2 input,
            float deadZone = DefaultDeadZone,
            DirectionPriority priority =
                DirectionPriority.Horizontal,
            Vector2Int previousDirection = default,
            float tieTolerance = DefaultTieTolerance)
        {
            ValidateTieTolerance(tieTolerance);
            ValidatePriority(priority);

            input = ApplyDeadZone(input, deadZone);

            if (input == Vector2.zero)
            {
                return Vector2Int.zero;
            }

            // 各入力軸の絶対値。
            float absX = Mathf.Abs(input.x);
            float absY = Mathf.Abs(input.y);

            // 水平方向の候補。
            Vector2Int horizontalDirection =
                input.x > 0f
                    ? Vector2Int.right
                    : input.x < 0f
                        ? Vector2Int.left
                        : Vector2Int.zero;

            // 垂直方向の候補。
            Vector2Int verticalDirection =
                input.y > 0f
                    ? Vector2Int.up
                    : input.y < 0f
                        ? Vector2Int.down
                        : Vector2Int.zero;

            // 片方の軸にしか入力がない場合。
            if (horizontalDirection == Vector2Int.zero)
            {
                return verticalDirection;
            }

            if (verticalDirection == Vector2Int.zero)
            {
                return horizontalDirection;
            }

            // 水平方向の入力が明確に強い場合。
            if (absX - absY > tieTolerance)
            {
                return horizontalDirection;
            }

            // 垂直方向の入力が明確に強い場合。
            if (absY - absX > tieTolerance)
            {
                return verticalDirection;
            }

            // 両軸の強さが同程度の場合。
            switch (priority)
            {
                case DirectionPriority.Vertical:

                    return verticalDirection;

                case DirectionPriority.PreviousDirection:

                    // 前回方向が現在の入力候補に
                    // 含まれている場合は維持する。
                    if (previousDirection ==
                            horizontalDirection ||
                        previousDirection ==
                            verticalDirection)
                    {
                        return previousDirection;
                    }

                    return horizontalDirection;

                default:

                    return horizontalDirection;
            }
        }

        /// <summary>
        /// 2軸入力を斜め方向を含む8方向へ変換する。
        ///
        /// 入力角度を45度単位に分割し、
        /// 最も近い方向を取得する。
        /// </summary>
        /// <param name="input">入力ベクトル</param>
        /// <param name="deadZone">デッドゾーンの半径</param>
        /// <returns>8方向の単位方向。無入力時はzero</returns>
        public static Vector2Int ToEightDirection(
            Vector2 input,
            float deadZone = DefaultDeadZone)
        {
            input = ApplyDeadZone(input, deadZone);

            if (input == Vector2.zero)
            {
                return Vector2Int.zero;
            }

            // 右方向を0度とした入力角度。
            float angle =
                Mathf.Atan2(input.y, input.x) *
                Mathf.Rad2Deg;

            // 入力角度を最も近い45度単位へ変換する。
            int index = Mathf.FloorToInt(
                (angle + 22.5f) / 45f);

            // 負のインデックスを0～7に補正する。
            index = (index % 8 + 8) % 8;

            return EightDirections[index];
        }

        #endregion

        #region Direction Validation Methods

        /// <summary>
        /// 指定方向が上下左右の単位方向か確認する。
        /// </summary>
        /// <param name="direction">確認する方向</param>
        /// <returns>4方向のいずれかの場合はtrue</returns>
        public static bool IsFourDirection(
            Vector2Int direction)
        {
            return direction == Vector2Int.up ||
                   direction == Vector2Int.down ||
                   direction == Vector2Int.left ||
                   direction == Vector2Int.right;
        }

        /// <summary>
        /// 指定方向が斜めを含む8方向の単位方向か確認する。
        /// </summary>
        /// <param name="direction">確認する方向</param>
        /// <returns>8方向のいずれかの場合はtrue</returns>
        public static bool IsEightDirection(
            Vector2Int direction)
        {
            return direction != Vector2Int.zero &&
                   direction.x >= -1 &&
                   direction.x <= 1 &&
                   direction.y >= -1 &&
                   direction.y <= 1;
        }

        /// <summary>
        /// 指定方向が斜め方向か確認する。
        /// </summary>
        /// <param name="direction">確認する方向</param>
        /// <returns>斜め方向の場合はtrue</returns>
        public static bool IsDiagonalDirection(
            Vector2Int direction)
        {
            return IsEightDirection(direction) &&
                   direction.x != 0 &&
                   direction.y != 0;
        }

        /// <summary>
        /// 2つの方向が互いに逆方向か確認する。
        /// </summary>
        /// <param name="first">比較元の方向</param>
        /// <param name="second">比較先の方向</param>
        /// <returns>互いに逆方向の場合はtrue</returns>
        public static bool IsOppositeDirection(
            Vector2Int first,
            Vector2Int second)
        {
            return IsEightDirection(first) &&
                   IsEightDirection(second) &&
                   first == -second;
        }

        #endregion

        #region Validation Methods

        /// <summary>
        /// 入力ベクトルの各成分が有限値か確認する。
        /// </summary>
        /// <param name="input">確認する入力値</param>
        /// <returns>有限値の場合はtrue</returns>
        private static bool IsFinite(Vector2 input)
        {
            return !float.IsNaN(input.x) &&
                   !float.IsInfinity(input.x) &&
                   !float.IsNaN(input.y) &&
                   !float.IsInfinity(input.y);
        }

        /// <summary>
        /// デッドゾーンの設定値を検証する。
        /// </summary>
        /// <param name="deadZone">確認する設定値</param>
        private static void ValidateDeadZone(
            float deadZone)
        {
            if (float.IsNaN(deadZone) ||
                float.IsInfinity(deadZone) ||
                deadZone < 0f ||
                deadZone >= 1f)
            {
                throw new ArgumentOutOfRangeException(
                    nameof(deadZone),
                    "デッドゾーンは0以上1未満にしてください。");
            }
        }

        /// <summary>
        /// 軸の強さを比較する許容値を検証する。
        /// </summary>
        /// <param name="tolerance">確認する許容値</param>
        private static void ValidateTieTolerance(
            float tolerance)
        {
            if (float.IsNaN(tolerance) ||
                float.IsInfinity(tolerance) ||
                tolerance < 0f ||
                tolerance > 1f)
            {
                throw new ArgumentOutOfRangeException(
                    nameof(tolerance),
                    "許容値は0以上1以下にしてください。");
            }
        }

        /// <summary>
        /// 優先方向の設定値を検証する。
        /// </summary>
        /// <param name="priority">確認する優先方向</param>
        private static void ValidatePriority(
            DirectionPriority priority)
        {
            switch (priority)
            {
                case DirectionPriority.Horizontal:
                case DirectionPriority.Vertical:
                case DirectionPriority.PreviousDirection:

                    return;

                default:

                    throw new ArgumentOutOfRangeException(
                        nameof(priority));
            }
        }

        #endregion
    }
}
